'use strict';
const searchAPI=globalThis.RasnikiSearch,collection=globalThis.RasnikiCatalog,get=id=>document.getElementById(id);let currentPage=1;
function renderSearch(){get('results').replaceChildren();try{const result=collection.paginate(searchAPI.find(collection.entries,get('query').value,get('mode').value),currentPage);currentPage=result.page;for(const entry of result.rows){const article=document.createElement('article'),heading=document.createElement('h2'),reason=document.createElement('p'),purpose=document.createElement('p'),link=document.createElement('a');heading.textContent=entry.name;reason.textContent=entry.status+' · '+entry.reason;purpose.textContent=entry.purpose;link.textContent='Summon draft workspace';link.href='catalogue.html#module='+encodeURIComponent(entry.id);article.append(heading,reason,purpose,link);get('results').append(article);}get('status').textContent=result.total+' matches · page '+result.page+' of '+result.pages;get('previous').disabled=result.page===1;get('next').disabled=result.page===result.pages;}catch(error){get('status').textContent=error.message;get('previous').disabled=true;get('next').disabled=true;}}
get('query').addEventListener('input',()=>{currentPage=1;renderSearch();});get('mode').addEventListener('change',()=>{currentPage=1;renderSearch();});get('previous').addEventListener('click',()=>{currentPage--;renderSearch();});get('next').addEventListener('click',()=>{currentPage++;renderSearch();});get('calculate').addEventListener('click',()=>{try{get('answer').textContent=searchAPI.calculate(get('a').value,get('b').value,get('op').value);}catch(error){get('answer').textContent=error.message;}});renderSearch();
